public sealed class Rng {
  public ulong State;
  public Rng(ulong seed) => State = seed;
  public uint NextU32() { /* PCG32 or mulberry32 step */ }
  public double Next01() => NextU32() / 4294967296.0;
  public int Int(int min, int maxIncl) => min + (int)(Next01() * (maxIncl - min + 1));
  public bool Chance(double p) => Next01() < p;
}
public sealed class RngStreams { public Rng Map, Weather, Events, Loot, Battle, Ai; }

