public interface IHourly { void Hour(World w, SimContext ctx); }
public interface IDaily  { void Day(World w, SimContext ctx); }
public sealed class Scheduler {
  readonly List<IHourly> _hourly; readonly List<IDaily> _daily;
  public void RunHour(World w, SimContext ctx) {
    w.Hour++; foreach (var s in _hourly) s.Hour(w, ctx);
    if (w.Hour % 24 == 0) foreach (var d in _daily) d.Day(w, ctx);
  }
}
