public readonly record struct HexCoord(int Q, int R) { public int S => -Q - R; }
public sealed class HexGrid {
  public readonly int Width, Height;
  public TileId Id(int x, int y) => new(y * Width + x);
  public HexCoord ToAxial(TileId id) { int x = id.Value % Width, y = id.Value / Width; return new(x - (y - (y & 1)) / 2, y); }
  public int Distance(TileId a, TileId b);
  public IEnumerable<TileId> Neighbours(TileId id);
  public IEnumerable<TileId> Within(TileId c, int r);
}
